mapper.select:
SELECT uaub.user_id, uaub.user_account, uaub.user_password, uaub.user_key, uaub.user_delete, uaub.rights_group_id, uarg.rights_group_id, uarg.rights_group_name, uarg.rights_group_add_time, uarg.rights_limits_all, uaub.head_portrait, uaub.user_realname FROM ${database.prefix.userms}hou_user_admin_base uaub LEFT JOIN ${database.prefix.userms}hou_user_admin_rights_group uarg ON uaub.rights_group_id = uarg.rights_group_id LEFT JOIN hou_${database.prefix.userms}hou_user_info_detail uate ON uate.user_id = uaub.user_id WHERE uaub.user_account = #{userAccount}
and uaub.user_password = #{password},
and uaub.user_delete = 0
